parameters.functionCode:
const items = $input.all();
const brokenLinks = [];
const redirects = [];
const healthy = [];

for (const item of items) {
  const response = item.json;
  const url = $node['Batch URLs'].json.url || $node['Batch URLs'].json.target_url || $node['Batch URLs'].json.url_ranked;
  const statusCode = response.statusCode || response.status || 0;

  if (statusCode >= 400 || statusCode === 0) {
    brokenLinks.push({
      url: url,
      status_code: statusCode,
      error: response.error || `HTTP ${statusCode}`
    });
  } else if (statusCode >= 300 && statusCode < 400) {
    redirects.push({
      url: url,
      status_code: statusCode,
      redirect_to: response.headers?.location || 'Unknown'
    });
  } else {
    healthy.push({ url: url, status_code: statusCode });
  }
}

return [{
  json: {
    total_checked: items.length,
    broken: brokenLinks,
    redirects: redirects,
    healthy_count: healthy.length,
    broken_count: brokenLinks.length,
    redirect_count: redirects.length,
    has_broken: brokenLinks.length > 0
  }
}];

parameters.text:
