• ✅ Healthy: {{ $json.healthy_count }}
• ❌ Broken: {{ $json.broken_count }}
• ↪️ Redirects: {{ $json.redirect_count }}

{{ $json.broken_count > 0 ? '*Broken Links:*\n' + $json.broken.map(b => `• ${b.url} → ${b.status_code} ${b.error}`).join('\n') : '' }}

{{ $json.redirect_count > 0 ? '\n*Redirects (consider updating):*\n' + $json.redirects.slice(0, 5).map(r => `• ${r.url} → ${r.status_code} → ${r.redirect_to}`).join('\n') : '' }}

